def find_siblings(numbers, n):
    """Return the number of pairs (x, y) where y = x + n such that gcd(x, y) = 1."""
    result = 0
    for num in numbers:
        for i in range(max(0, num - n + 1), len(numbers)):
            if gcd(num, numbers[i]) == 1:
                result += 1
    return result

def find_kids_from_start(numbers, l, r, visible_first=False):
    """Return a subset of children indexed from l to r who are not visible from the start."""
    from collections import deque
    queue = deque(range(l, r + 1))
    auto = True
    while len(queue) > 1:
        auto = not auto
        current = queue.popleft()
        if auto:
            if visible_first:
                queue.append(-1)
            for other in range(min(current, r), current + 1):
                if numbers[other] >= current:
                    return queue
        else:
            if visible_first:
                queue.append(current)
            for other in range(max(0, current - n), current):
                if numbers[other] >= current:
                    return queue
    return queue

