from collections import defaultdict

def main():
    # Read the number of lines from standard input
    n = int(input())

    # Read the lines from standard input and store them in a list
    lines = [list(map(int, input().split())) for _ in range(n)]

    # Create a dictionary to store precomputation values
    precomputation = defaultdict(int)

    # Function to perform mirror operation on a line (ai, bi) to turn it into (ai1, bi2)
    def mirror(point, other):
        ai, bi = point
        ai1, bi1 = other
        return bi1, bi - bi1 + 1, ai1 + 1, ai - ai1 + 1

    # Function to get the edge with the minimum distance to two given nodes
    def find_edge(v, w):
        all_edges = {x for p, x, y, z in lines for x, y in (p, z)}
        for p, x, y, z in lines:
            if p == v and y == w:
                break
            if z == v and x == w:
                break
        return sorted(all_edges - {v, w}, key=lambda x: lines[x][2])

    # Create a map of reversed endpoints and edges
    reversed_edges = defaultdict(int)
    endpoints = dict()

    # Create a map of endpoints and mirrored end points
    endpoints = {x: y for x, y, z, v in lines}

    # Create a map of edge indices
    all_edges = {i for p, x, y, z in lines for i in range(2)}

    # Precompute distance information for each edge
    for i in all_edges:
        x, y, z, v = lines[i - 1]
        end_point = endpoints[z]
        reversed_edge = mirror(end_point, x) if x == v else mirror(end_point, y)

        # Store or update the minimum distance for this line
        precomputation[min(precomputation[reversed_edge], (i - 1) // 2)] += 1

    # Count the number of valid configurations
    count = 0
    for dist in sorted(precomputation.keys(), reverse=True):
        if precomputation[dist] >= 3:
            count += 1

    print(count)

