import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def find_prob(l, r):
    if l == r:
        return 0  # No pairs possible if there's only one person
    if r < 2 * l + 1:  # No pairs possible if there are fewer people than the number of gaps
        return 0

    steps = 0
    current = -1  # Always an even number initially (greatest common divisor between two consecutive numbers)

    # Count down from R to L
    for i in range(2, max([l, r // 2] + 1)):
        current -= 1
        delta = math.floor(math.sqrt((i - current) ** 2))
        if not delta:
            continue
        steps += delta

    return len(range(l, r + 1)) * math.factorial(steps + 1) // gcd(steps + 1, (steps + 1))

