def dfs(friends, target, visited, matched, n):
    if target in visited:
        return
    if not matched or friends[n - 1][1] <= friends[n - 1][0]:
        visited[target] = True
        matched.append([target, friends[target][1]])
    else:
        first, second = n - 1, n - 2
        while first >= 0 and (second + 1) + (first + 1) < second:
            if friends[first][0] < friends[second][0] and (friends[first][1] <= friends[second][0] or friends[first][1] <= friends[first + 1][0] or friends[second][1] > friends[first + 1][0]):
                second += 1
            if friends[first][0] > friends[second][0] and (friends[first][1] <= friends[second][0] or friends[first][1] <= friends[first + 1][0] or friends[second][1] > friends[second + 1][0]):
                first -= 1
        if friends[first][0] >= friends[second][0]:
            while friends[first][0] > friends[second][0]:
                if friends[first][1] <= friends[second][1]:
                    neighbors = [first + 1]
                    second += 1
                else:
                    neighbors = [first, first + 2]
                    second += 2
                for neighbor in neighbors:
                    if not visited[neighbor]:
                        dfs(friends, neighbor, visited, matched, n)
                        matched.append([neighbor, friends[neighbor][1]])
                break
        else:
            while friends[first][0] < friends[second][0]:
                if friends[first][1] <= friends[second][1]:
                    neighbors = [first]
                    first -= 1
                else:
                    neighbors = [first - 1]
                    first -= 2
                for neighbor in neighbors:
                    if not visited[neighbor]:
                        dfs(friends, neighbor, visited, matched, n)
                        matched.append([neighbor, friends[neighbor][1]])
        visited[target] = True


