def detect_viruses(gene_size, mutation_table, antibodies):
    raw_mountains = {(t[0], gene_size + abs(t[1] - gene_size)) for t in mutation_table}
    tested_antibody_coverages = {bitcount(av) for av in antibodies}
    return any(all(a in t for t in raw_mountains) for a in tested_antibody_coverages)


