def number_of_awkward_pairs(low, high):
    # We start with a base case - zero people creating an awkward pair. 
    # Then we update the values of p & above in a bottom-up fashion. 
    # (quadratic approach, let's assume q is number of people)
    p, above = 1, 1
    for i in range(1, max(low+1, high)):
        p, above = (p+above)*i // gcd(i, p), p

    # Adjusting for special case where low and high meet
    if low == high:
        return above % (10**9+7)
    else:
