def visible_stones(N, H, queries):
    max_height = -float('inf')
    max_height_indices = []
    visible_count = 0

    for i in range(N):
        if H[i] > max_height:
            max_height = H[i]
            max_height_indices = [i]
        elif H[i] == max_height:
            max_height_indices.append(i)

    for a, b in queries:
        current_max_height_indices = [a-1]
        current_max_height = H[b]
        for k in range(b-1, a-1, -1):
            if H[k] >= current_max_height:
                break
            current_max_height_indices.append(k)
        visible_count += len(max_height_indices) * len(current_max_height_indices)

    return visible_count


