from collections import defaultdict

def calculate_distances(edges):
    adjacency_list = defaultdict(list)
    for edge in edges:
        adjacency_list[edge[0]].append(edge[1])
        adjacency_list[edge[1]].append(edge[0])

    distances = [0] * (len(adjacency_list) * 2)
    for start, end in edges:
        distances[start * 2] = min(distances[(end - 1) * 2], distances[start * 2 + 1] + 1)
        distances[end * 2 + 1] = min(distances[(start - 1) * 2], distances[end * 2] + 1)

    return distances

def main():
