        edges.append((a, b - 1))
        edges.append((a, b))

    adjacency_list = defaultdict(list)
    for edge in edges:
        adjacency_list[edge[0]].append(edge[1])

    distances = calculate_distances(edges)
    iso_distances = [distances[i] for i in range(len(distances)) if distances[i] != 0]

    if len(iso_distances) < 3:
        return len(iso_distances)

    valid_pairs = set()
    for i in range(len(distances)):
        for j in range(i + 1, len(distances)):
            if abs(distances[i] - distances[j]) % 2 == 0:
                valid_pairs.add((i, j))
