def maxf(n):
    # Calculate the maximum Fibonacci number less than or equal to n
    ans = 1
    x, y = 1, 1
    while ans < n:
        x, y = y, x + y
        ans = x + y
    return x

def dp(prefix,sum):
    mod = 998244353  # 223*7*17 + 1
    f = [[0]*(n+1) for _ in range(n+1)]
    i,j = 0,0
    for x in range(1,n+1):
        f[0][x] = f[x][0] = sum[j] + 1
    while i <= x:
        if f[i][j] == maxf(n): 
            break
        j += 1
    for i in range(1, len(prefix)):
        for j in range(len(prefix[i-1])):
            k = prefix[i-1][j] - 1
            for m in range(n+1):
                f[i][k] = max(f[i][k], f[i-1][m])
    return min(f[len(prefix)][0], n)

def solve():
    n = int(input())
    p = list(map(int, input().split()))
    q = list(map(int, input().split()))
    r = [0] * n
    dep = 0
    for i, b in enumerate(p):
        if r[b] == 0 and i != 0 and q[b] == 0:
            k = dp(r[:i] + r[i+2:], sum(r[:i]) - 1)
            dep += (n*dep - (k-1))//2 % mod
            dep += (dep * dep - (k-1))//2 % mod
            dep += (k-1) * (n-k) // 2 % mod
            dep -= dep*(n-k-1) // 2 % mod
            dep += (k * (k-1) - (n-k)) // 2 % mod
            r[b] = i + 1
    return dep

