def min_energy_req(n, m, k, transformers):
    x, y, d, t, e = transformers.pop()
    intersections_by_x = defaultdict(set)
    intersections_by_y = defaultdict(set)
    intersects = set()

    # Calculate intersections and energies
    max_x = x + t * d + t - t % (2 * d)
    max_y = y + t * d - t % (2 * d)
    if max_x < n or max_y < m or max_x >= n or max_y >= m:
        return 0
    for step in range(t + 1):
        next_x = x + step * d
        next_y = y + step * d
        if next_x < n and next_y < m:
            intersections_by_x[next_x].add((next_y, e // step))
            intersections_by_y[next_y].add((next_x, e // step))
        if next_x >= n or next_y >= m:
            intersects.add((next_x, next_y))
        if next_x >= max_x or next_y >= max_y:
            break

    # Score intersections based on closest x, then y
    min_intersections = []
    for (x_val, e_val) in intersections_by_x:
        for (y_val, val) in intersections_by_y[x_val]:
            if (x_val, y_val) not in intersects:
                val /= n if minimize(x_val, m - e_val - y_val) else m - e_val - y_val
                heapq.heappush(min_intersections, (-val, (x_val, y_val)))
            elif x_val < n and y_val < m and minimize(x_val, m - e_val - y_val):
                val /= n if minimize(x_val + 1, m - e_val - y_val) else m - e_val - y_val
                heapq.heappush(min_intersections, (-val, (x_val + 1, y_val)))
            elif minimize(x_val + 1, m - e_val - y_val):
                val /= m - e_val - y_val
