from typing import List
from itertools import accumulate

def max_sum_subarrays(nums: List[int], k: int) -> int:
    n = len(nums)
    nums.sort()
    total_sum = sum(nums)
    power_set_combinations = []
    for i in range(1, k + 1):
        power_set_combinations.append(list(accumulate([0] * i)))

    # Merge power set combinations
    for i in range(len(power_set_combinations)):
        for j in range(1, len(power_set_combinations)):
            power_set_combinations[i].extend(power_set_combinations[j])

    candidate_states = [[0] * (n + 1) for _ in range(len(power_set_combinations))]
    best_result = 0

    for state in power_set_combinations:
        for num in nums:
            if candidate_states[state[len(state) - 1]][num + 1]:
                candidate_states[state[len(state) - 1]][num + 1] = False
                candidate_states[state[len(state) - 2]][num + 1] = True
            yes_state = 0
            for i in range(len(state) - 1):
                if state[i] + 1 == num + 1:
                    yes_state += state[i]
            new_state = state[:]
            new_state.append(yes_state)
            best_result = max(best_result, total_sum - candidate_states[yes_state][num + 1] + yes_state * num)

    return best_result
