def calculate_mutual_distance(endpoints, line_contributions, required_distance):
    def reciprocal_distance(p1, p2):
        return max((p1 - p2 + (2 * endpoints - p2) % endpoints) % endpoints - 1, 0)

    directions = [(0, 1), (1, 0)]  # Moving counterclockwise
    midpoint = (len(endpoints) // 2, 0)
    index = directions.index(line_contributions[midpoint])

    # Initialize counts
    orientation_left = 0
    orientation_right = 0
    for i in range(len(endpoints)):
        index = (directions.index(line_contributions[i % len(endpoints)]) + index - 1) % len(directions)
        if index == 0:
            orientation_right += 1
        elif index == len(directions) - 1:
            orientation_left += 1

    # Check for required distance
    return reciprocal_distance(endpoints[(midpoint[0] + required_distance) % len(endpoints)], midpoint[0]) == reciprocal_distance(endpoints[(midpoint[0] - required_distance) % len(endpoints)], midpoint[0])
