import math

# Define a function to calculate the Euclidean distance between two points
def distance(x1, y1, x2, y2):
    return math.sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)

# Helper function to check if three points are collinear
def are_collinear(x1, y1, x2, y2, x3, y3):
    return (x2 - x1) * (y3 - y1) == (x3 - x1) * (y2 - y1)

# Function to calculate the radius of the circle that passes through three given points
def calculate_circle_radius(x1, y1, x2, y2, x3, y3):
    A = (x1 - x2) * (y1 - y2)
    B = (x1 - x3) * (y1 - y3)
    C = (x1 - x2) * (x1 - x3)
    D = (y1 - y2) * (y1 - y3)
    E = (y1 - y2) * (y2 - y3)
    return abs(2 * A * (x3 * D - y3 * E) - 2 * B * (x3 * E - y3 * D)) / (2 * distance(x1, y1, x2, y2))

# Function to find the three points that maximize the expected number of fans in the photo
def find_high_rising_points(fans):
    max_radius_points = []

    for i in range(1, len(fans)):
        for j in range(i + 1, len(fans)):
            for k in range(j + 1, len(fans)):
                x1, y1 = fans[i][0], fans[i][1]
                x2, y2 = fans[j][0], fans[j][1]
                x3, y3 = fans[k][0], fans[k][1]

                # Check if the three points are collinear
                if are_collinear(x1, y1, x2, y2, x3, y3):
                    continue

                # Calculate the radius of the circle passing through the three points
                circle_radius = calculate_circle_radius(x1, y1, x2, y2, x3, y3)
                if circle_radius > 0:
