def max_possible_sum(n, k, arr):
    if n == 1:
        return arr[0]

    left, right = 0, n
    while left + 1 < right:
        mid = (left + right) // 2
        i = j = 0

        for a in arr:
            while j < n and i < k and arr[j] - arr[i] < mid:
                j += 1
            if j == n:
                break
            i = j

        if i == k and right - left <= 1:
            return left + right
        elif j < n:
            return max(max_of_subarray(arr[:k]), i + mid * j)
        elif j == n and left + 1 < right:
            right = mid
        else:
            left = mid

    return left + right

def max_of_subarray(sub):
    return sum(sub)

